#include <iostream>
struct Shape {
    virtual int score() const = 0;
    virtual ~Shape() = default;
};
struct Square : Shape {
    int score() const override { return 4; }
};
void show(const Shape& shape) { std::cout << shape.score() << '\n'; }
int main() {
    Square square;
    show(square);
}

